<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Lotte Tower Artwork</title>
    <style>
        body {
            margin: 0;
            font-family: Arial, sans-serif;
            overflow-x: hidden;
        }
        #container {
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        #canvas-container {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            width: 100%;
            max-width: 1440px;
            overflow-x: auto;
        }
        canvas {
            margin: 10px;
            border: 1px solid #000;
        }
        #controls {
            margin-top: 20px;
        }
        #controls button {
            font-size: 19px;
            padding: 10px;
            margin: 5px;
        }
    </style>
</head>
<body>
    <div id="container">
        <div id="canvas-container">
            <canvas id="site-plan" width="375" height="375"></canvas>
            <canvas id="floor-plan" width="375" height="375"></canvas>
            <canvas id="elevation" width="375" height="375"></canvas>
            <canvas id="section" width="375" height="375"></canvas>
        </div>
        <div id="stages">
            <canvas id="stage1" width="375" height="375"></canvas>
            <canvas id="stage2" width="375" height="375"></canvas>
            <canvas id="stage3" width="375" height="375"></canvas>
            <canvas id="final" width="375" height="375"></canvas>
        </div>
        <div id="controls">
            <button onclick="renderStage1()">Stage 1</button>
            <button onclick="renderStage2()">Stage 2</button>
            <button onclick="renderStage3()">Stage 3</button>
            <button onclick="renderFinal()">Final</button>
        </div>
    </div>
    <script>
        const canvasElements = {
            site: document.getElementById('site-plan'),
            floor: document.getElementById('floor-plan'),
            elevation: document.getElementById('elevation'),
            section: document.getElementById('section'),
            stage1: document.getElementById('stage1'),
            stage2: document.getElementById('stage2'),
            stage3: document.getElementById('stage3'),
            final: document.getElementById('final')
        };

        const ctxElements = {
            site: canvasElements.site.getContext('2d'),
            floor: canvasElements.floor.getContext('2d'),
            elevation: canvasElements.elevation.getContext('2d'),
            section: canvasElements.section.getContext('2d'),
            stage1: canvasElements.stage1.getContext('2d'),
            stage2: canvasElements.stage2.getContext('2d'),
            stage3: canvasElements.stage3.getContext('2d'),
            final: canvasElements.final.getContext('2d')
        };

        function drawSitePlan() {
            ctxElements.site.clearRect(0, 0, 375, 375);
            // Drawing code for site plan
        }

        function drawFloorPlan() {
            ctxElements.floor.clearRect(0, 0, 375, 375);
            // Drawing code for floor plan
        }

        function drawElevation() {
            ctxElements.elevation.clearRect(0, 0, 375, 375);
            // Drawing code for elevation
        }

        function drawSection() {
            ctxElements.section.clearRect(0, 0, 375, 375);
            // Drawing code for section
        }

        function renderStage1() {
            drawSitePlan();
            drawFloorPlan();
            // Additional stage 1 rendering code
        }

        function renderStage2() {
            drawSitePlan();
            drawFloorPlan();
            // Additional stage 2 rendering code
        }

        function renderStage3() {
            drawSitePlan();
            drawFloorPlan();
            // Additional stage 3 rendering code
        }

        function renderFinal() {
            drawSitePlan();
            drawFloorPlan();
            // Final rendering code
        }

        // Initial rendering
        drawSitePlan();
        drawFloorPlan();
        drawElevation();
        drawSection();
    </script>
</body>
</html>
